</SfSlider>

@code {
    private int sliderValue = 30;

    private void OnTicksRendered(SliderTickRenderedEventArgs args)
    {
        // Apply custom styling or animations to rendered ticks
        args.HtmlAttributes = new Dictionary<string, object> 
        { 
